css:
/* --- 基礎設置 --- */
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", "Arial", sans-serif;
  font-weight: 500;
  box-sizing: border-box;
}

.widget-container {
  width: 100%;
  height: 100%;
  background: #000;
  border-radius: 22px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.icon {
  width: 22px;
  height: 22px;
  stroke: #fff;
  fill: none;
}

/* --- 頂部欄 --- */
.top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 12px;
  flex-shrink: 0;
  z-index: 10;
}
.chevron-icon {
  width: 18px; height: 18px; stroke: #888;
  background: rgba(40,40,40,0.7);
  padding: 2px; border-radius: 4px;
}
.live-icon { stroke: #f5d300; }

/* --- 相機預覽 --- */
.camera-view {
  flex-grow: 1;
  width: 100%;
  min-height: 50%;
  background-color: #333;
  background-size: cover;
  background-position: center;
}

/* --- 底部控制 --- */
.bottom-controls {
  padding: 4px 0 0 0; /* 移除底部padding，通过action-bar控制 */
  display: flex;
  flex-direction: column;
  gap: 4px; /* 缩小与模式选择的间距 */
  flex-shrink: 0;
}

.mode-selector {
  display: flex;
  justify-content: center;
  gap: 16px;
  white-space: nowrap;
  width: 100%;
  overflow: hidden;
  color: #8e8e93;
  font-size: 11px;
  position: relative;
}
.mode-selector::before, .mode-selector::after {
    content: ''; position: absolute; width: 30px;
    height: 100%; top: 0; z-index: 1;
}
.mode-selector::before { left: 0; background: linear-gradient(to right, #000, transparent); }
.mode-selector::after { right: 0; background: linear-gradient(to left, #000, transparent); }
.mode-selector span.active { color: #F5D300; }

.action-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 20px 8px 20px; /* 调整边距并增加底部空间 */
  position: relative;
}

.gallery-preview,
.switch-camera-button {
  transform: translateY(-2px); /* 【修改】向上移动10px */
}

.gallery-preview {
  width: 32px; /* 【修改】保持尺寸 */
  height: 32px;
  border-radius: 6px;
  background-color: #222;
  background-size: cover;
  background-position: center;
}

.shutter-button {
  width: 30px; /* 【修改】再次缩小 */
  height: 30px;
  background: #fff;
  border-radius: 50%;
  border: 2px solid #000;
  box-shadow: 0 0 0 1px #fff;
}

.switch-camera-button {
  width: 30px;
  height: 30px;
  background: #2c2c2e;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.switch-camera-button .icon {
  width: 18px; /* 【修改】恢复第一版图标的样式 */
  height: 18px;
}

/* ================= 全局容器 ================= */
.mz-music-chat-4x2 {
  width: 100%; height: 100%; position: relative; overflow: hidden;
  border-radius: 24px; box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  display: flex; flex-direction: column;
  /* 没有任何多余的背景代码，全部移交 JS 实时掌控 */
}

/* ================= 1. 顶部音乐模块 ================= */
.music-module {
  border-radius: 20px;
  margin: clamp(10px, 3vw, 14px); 
  padding: clamp(10px, 3vw, 14px);
  display: flex; align-items: center; gap: clamp(10px, 3vw, 14px);
  flex: 1.1; 
}

.album-cover {
  width: clamp(50px, 14vw, 64px); height: clamp(50px, 14vw, 64px);
  border-radius: 10px; background-color: rgba(255,255,255,0.1);
  overflow: hidden; flex-shrink: 0;
}
.album-cover img { width: 100%; height: 100%; object-fit: cover; }

.music-info { display: flex; flex-direction: column; justify-content: center; min-width: 60px; }
.song-name { font-size: clamp(14px, 3.5vw, 17px); font-weight: 700; color: var(--song-color); white-space: nowrap; }
.artist-name { font-size: clamp(11px, 2.5vw, 13px); color: var(--artist-color); margin-top: 2px; }
.app-logo { display: flex; align-items: center; gap: 4px; margin-top: 6px; }
.app-logo span { font-size: clamp(10px, 2vw, 11px); font-weight: 600; color: var(--app-color); }

.svg-apple { width: 11.5px; height: 13.5px; color: var(--app-color); }
.svg-pause { width: 11px; height: 11px; color: var(--play-icon-color); }
.svg-chat-icon { width: 12px; height: 12px; color: var(--bottom-text); }

.lyrics-box {
  flex: 1; 
  padding: clamp(10px, 2.8vw, 14px) clamp(12px, 3.5vw, 18px); 
  border-radius: 12px;
  color: var(--lyrics-color); font-size: clamp(11px, 2.5vw, 13px); font-weight: 500;
  display: flex; align-items: center; justify-content: center; text-align: center;
}

.play-btn { flex-shrink: 0; display: flex; justify-content: center; align-items: center; padding-right: 4px; }
.progress-ring {
  width: clamp(28px, 8vw, 36px); height: clamp(28px, 8vw, 36px);
  border-radius: 50%;
  border: 2.5px solid transparent; /* 由 JS 填充颜色 */
  display: flex; justify-content: center; align-items: center;
}

/* ================= 2. 底部排版模块 ================= */
.bottom-module {
  flex: 0.9; padding: 0 clamp(16px, 4vw, 20px) clamp(12px, 3vw, 16px);
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
}

.date-col {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: var(--bottom-text); font-size: clamp(11px, 2.8vw, 14px); font-weight: 600;
  letter-spacing: 1px; min-width: 50px; flex-shrink: 0;
}
.dashed-line {
  width: 100%; border-bottom: 2px dashed rgba(255,255,255,0.2); 
  border-bottom-color: var(--bottom-text);
  margin: 4px 0; opacity: 0.4;
}

.chat-col { flex: 1; display: flex; flex-direction: column; gap: 8px; align-items: flex-end; overflow: hidden; }
.chat-row { display: flex; align-items: center; gap: 6px; max-width: 100%; }
.chat-time { color: var(--bottom-text); font-size: clamp(9px, 2vw, 11px); font-weight: 500; font-family: monospace; }
.chat-bubble {
  padding: 5px 12px; border-radius: 12px; 
  font-size: clamp(10px, 2.3vw, 12px); font-weight: 600;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 160px;
  background-color: var(--bubble-bg); 
  color: var(--bubble-text);
}

.ios-widget {
  width: 100%;
  height: 100%;
  padding: 16px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: rgba(60, 60, 60, 0.4); 
  backdrop-filter: blur(25px);
  -webkit-backdrop-filter: blur(25px);
  border-radius: 32px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  color: #ffffff;
  overflow: hidden;
}

.header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 4px;
}

.title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
}

.date {
  font-size: 14px;
  font-weight: 600;
  opacity: 0.9;
}

.status-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  padding: 6px 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.pill {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
}

.battery-pill {
  flex: 1;
  justify-content: space-between;
  padding: 6px 12px;
  gap: 8px;
}

/*⁣​⁠⁠‍‌‍‌‍‍‌⁠​‌⁠​‌‌⁠⁠‍⁠‍​​⁠‌​​​‌‌⁠‍​⁠⁠​‍‍‍⁠​‌​⁠‌⁠​‌‌⁠⁠​‌‌‍‌‍⁠‍‍‌‍⁠⁣ 电池外框 */
.battery-icon {
  width: 22px;
  height: 12px;
  border: 1.5px solid #fff;
  border-radius: 3px;
  position: relative;
  box-sizing: border-box;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 电池正极小凸起 */
.battery-icon::after {
  content: "";
  position: absolute;
  right: -4px;
  top: 2px;
  width: 2px;
  height: 4px;
  background: #fff;
  border-radius: 0 1px 1px 0;
}

/* 内部白色满格电量 */
.battery-level {
  position: absolute;
  top: 1px;
  left: 1px;
  right: 1px;
  bottom: 1px;
  background: #ffffff;
  border-radius: 1px;
}

/* 满格中的符号 */
.battery-symbol {
  position: relative;
  z-index: 2;
  color: #000000;
  font-size: 9px;
  line-height: 1;
  font-weight: bold;
}

.battery-text {
  font-size: 12px;
  font-weight: 600;
}

.icon-pill {
  width: 34px;
  height: 34px;
  color: #fff;
  flex-shrink: 0;
}

.image-card {
  position: relative;
  flex: 1;
  border-radius: 20px;
  overflow: hidden;
  background: #222;
}

.image-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.my-custom-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  background: #fff;
  border-radius: 20px;
}
.my-custom-box img {
  width: 50px;
  height: 50px;
  border-radius: 50%;
}
/*⁣⁠‍‍‌​⁠‌‌⁠‍‍‍⁠⁠​‌‍‍⁠‌⁠​​‌​​‌‍⁠‍⁠​⁠‌‍⁠​‌‍⁠‌​‌⁠‍‍‍​‌​‍‌‍‍‍‌‌‍​​‍⁠‌‌⁣*/

.profile-widget {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  height: 100%;
  padding: 5px; 
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", sans-serif;
}

.side-column {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 70%; 
}

.left-column { align-items: flex-start; }
.right-column { align-items: flex-end; }

/* 玻璃质感标签（已去白边） */
.glass-tag {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px; 

  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);

  /* 核心修改：删除了 border，去掉了外面的白边 */

  border-radius: 30px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
  white-space: nowrap; 
}

.tag-icon {
  font-size: 13px; 
  color: #333333;
  flex-shrink: 0; 
}

.tag-text {
  font-size: 12px; 
  font-weight: 600;
  color: #333333; 
}

/* ================= 中间头像与文字 ================= */
.center-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px; 
  flex-shrink: 0; 
  padding: 0 5px; 
}

.avatar-box {
  width: 95px; 
  height: 95px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.2); 
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.footer-decor {
  color: #ffffff; 
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 2px;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.6);
}

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background-color: transparent !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
}

/*⁣​⁠⁠‍‌‍‌‍‍‌⁠​‌⁠​‌‌⁠⁠‍⁠‍​​⁠‌​​​‌‌⁠‍​⁠⁠​‍‍‍⁠​‌​⁠‌⁠​‌‌⁠⁠​‌‌‍‌‍⁠‍‍‌‍⁠⁣⁣⁠‍‍‌​⁠‌‌⁠‍‍‍⁠⁠​‌‍‍⁠‌⁠​​‌​​‌‍⁠‍⁠​⁠‌‍⁠​‌‍⁠‌​‌⁠‍‍‍​‌​‍‌‍‍‍‌‌‍​​‍⁠‌‌⁣ --- 預設模式 1：純白底 (淺色) --- */
.widget-container {
  width: 96%;
  height: 85%; /* 【修改】整體高度略微壓扁 */
  border-radius: 22px; 
  background-color: #ffffff; 
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  /* 【修改】上下內邊距縮窄，從 12px 減為 10px */
  padding: 10px 16px;
  box-sizing: border-box;

  /* 轉場動畫 */
  transition: background-color 0.3s ease, backdrop-filter 0.3s ease, box-shadow 0.3s ease;

  /* 純白底文字色 */
  --title-color: #000000;
  --msg-color: #888888; 
  --time-color: #888888;
}

/* --- 模式 2：深色磨砂玻璃 --- */
.widget-container.dark-glass {
  background-color: rgba(45, 45, 45, 0.65); /* 半透明深灰色 */
  backdrop-filter: blur(25px) saturate(120%); /* 加入一點飽和度讓透出的桌布更好看 */
  -webkit-backdrop-filter: blur(25px) saturate(120%);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2);

  /* 深色底文字色 */
  --title-color: #ffffff;
  --msg-color: #bbbbbb; 
  --time-color: #aaaaaa;
}

/* --- 模式 3：白色磨砂玻璃 --- */
.widget-container.light-glass {
  background-color: rgba(255, 255, 255, 0.4); /* 高透明度的白色 */
  /* 強烈模糊 + 些微提亮，製造高級玻璃感 */
  backdrop-filter: blur(30px) brightness(110%);
  -webkit-backdrop-filter: blur(30px) brightness(110%);
  /* 玻璃邊緣需要一點微弱的白邊來勾勒立體感 */
  border: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.1);

  /* 白色玻璃文字色 (同預設) */
  --title-color: #000000;
  --msg-color: #666666; /* 稍微加深一點點，以免在亮桌布上看不清 */
  --time-color: #666666;
}

/* --- 左側圖標 --- */
.icon-section {
  flex-shrink: 0;
  margin-right: 12px;
  cursor: pointer;
}
.icon-section:active .icon-wrapper {
  transform: scale(0.92);
}

.icon-wrapper {
  width: 44px; /* 這裡維持正方形，配合容器變扁，它會顯得更緊湊 */
  height: 44px;
  border-radius: 10px; 
  background-color: #e5e5e5; 
  overflow: hidden;
  transition: transform 0.15s ease;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-icon {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
img[src=""] { display: none; }

/* --- 中間文字 --- */
.text-section {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.top-text {
  font-size: 15px;
  font-weight: 600;
  color: var(--title-color);
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 0.3s ease;
}

.bottom-text {
  font-size: 13px;
  color: var(--msg-color);
  font-weight: 400;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 0.3s ease;
}

/* --- 右側時間 --- */
.time-section {
  flex-shrink: 0;
  margin-left: 8px;
  font-size: 12px;
  color: var(--time-color);
  align-self: flex-start; 
  margin-top: 3px;
  transition: color 0.3s ease;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: transparent; font-family: 'PingFang SC', 'Noto Sans SC', sans-serif; }
.card { background: #ffffff; border-radius: 18px; border: 0.5px solid rgba(0,0,0,0.08); padding: 0 0 10px; height: 100%; display: flex; flex-direction: column; gap: 0; }
.titlebar { display: flex; align-items: center; justify-content: center; position: relative; padding: 10px 16px; background: #f2f2f2; border-radius: 18px 18px 0 0; }
.back-btn { position: absolute; left: 12px; display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 8px; cursor: pointer; border: none; background: transparent; -webkit-tap-highlight-color: transparent; transition: background 0.15s; }
.back-btn:active { background: rgba(0,0,0,0.07); }
.title-text { font-size: 15px; font-weight: 600; color: #1a1a1a; letter-spacing: 0.03em; }
.body { display: flex; flex-direction: column; gap: 4px; padding: 7px 12px 0; }
.header { display: flex; align-items: center; gap: 10px; padding-left: 5px; }
.avatar { width: 38px; height: 38px; border-radius: 50%; flex-shrink: 0; overflow: hidden; border: 1.5px solid rgba(0,0,0,0.06); background: #e8d5c4; }
.user-info { display: flex; flex-direction: column; gap: 1px; }
.username { font-size: 13px; font-weight: 600; color: #1a1a1a; letter-spacing: 0.01em; }
.handle { font-size: 11px; color: #888; }
.content { font-size: 14px; color: #1a1a1a; line-height: 1.55; letter-spacing: 0.02em; flex: 1; padding-left: 5px; }
.meta { display: flex; align-items: center; justify-content: flex-end; gap: 5px; padding-left: 5px; }
.meta-text { font-size: 11px; color: #888; }
.divider { height: 0.5px; background: rgba(0,0,0,0.07); margin: 2px 0; }
.actions { display: flex; align-items: center; }
.action-btn { flex: 1; display: flex; align-items: center; justify-content: center; gap: 5px; padding: 6px 0; border-radius: 10px; cursor: pointer; border: none; background: transparent; -webkit-tap-highlight-color: transparent; user-select: none; transition: background 0.15s; }
.action-btn:active { background: rgba(0,0,0,0.05); }
.action-label { font-size: 12px; color: #888; font-weight: 400; transition: color 0.2s; }
.action-divider { width: 0.5px; height: 20px; background: rgba(0,0,0,0.07); }
.more-btn { width: 36px; display: flex; align-items: center; justify-content: center; padding: 6px 0; cursor: pointer; border-radius: 10px; border: none; background: transparent; -webkit-tap-highlight-color: transparent; transition: background 0.15s; }
.more-btn:active { background: rgba(0,0,0,0.05); }
.popup-overlay { position: fixed; inset: 0; z-index: 100; display: none; }
.popup-overlay.show { display: block; }
.popup { position: absolute; background: rgba(255,255,255,0.97); border-radius: 14px; border: 0.5px solid rgba(0,0,0,0.1); box-shadow: 0 8px 24px rgba(0,0,0,0.12); overflow: hidden; min-width: 100px; }
.popup-item { padding: 11px 20px; font-size: 13px; color: #1a1a1a; cursor: pointer; display: flex; align-items: center; gap: 8px; transition: background 0.12s; }
.popup-item:active { background: rgba(0,0,0,0.08); }
.popup-item.danger { color: #e05c72; }
.popup-sep { height: 0.5px; background: rgba(0,0,0,0.07); }
/*⁣​⁠⁠‍‌‍‌‍‍‌⁠​‌⁠​‌‌⁠⁠‍⁠‍​​⁠‌​​​‌‌⁠‍​⁠⁠​‍‍‍⁠​‌​⁠‌⁠​‌‌⁠⁠​‌‌‍‌‍⁠‍‍‌‍⁠⁣⁣⁠‍‍‌​⁠‌‌⁠‍‍‍⁠⁠​‌‍‍⁠‌⁠​​‌​​‌‍⁠‍⁠​⁠‌‍⁠​‌‍⁠‌​‌⁠‍‍‍​‌​‍‌‍‍‍‌‌‍​​‍⁠‌‌⁣*/

/*⁣⁠‍‍‌​⁠‌‌⁠‍‍‍⁠⁠​‌‍‍⁠‌⁠​​‌​​‌‍⁠‍⁠​⁠‌‍⁠​‌‍⁠‌​‌⁠‍‍‍​‌​‍‌‍‍‍‌‌‍​​‍⁠‌‌⁣ --- Global --- */
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  background-color: transparent;
  height: 100%;
  overflow: hidden;
}

/* --- Main Container --- */
.widget-container {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: #f2f2f7;
  border-radius: 24px;
}

/* --- Top Bar (No Change) --- */
.top-bar {
  display: flex;
  align-items: center;
  padding: 12px;
  background-color: rgba(242, 242, 247, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  color: #1d1d1f;
  flex-shrink: 0;
}

.thumbnail {
  width: 50px;
  height: 50px;
  border-radius: 8px;
  background-color: #e5e5ea;
  margin-right: 12px;
  overflow: hidden;
}

.thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.title-section {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.title-section span {
  font-size: 1em;
  font-weight: 600;
}

.options-button {
  background-color: rgba(229, 229, 234, 0.85);
  border-radius: 8px;
  padding: 4px 8px;
  font-size: 0.85em;
  font-weight: 500;
  color: #1d1d1f;
}

.close-button {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background-color: #e5e5ea;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  margin-left: 12px;
  color: #8a8a8e;
}

/* --- Image Gallery (v8 Final Version) --- */
.image-gallery {
  flex-grow: 1;
  display: flex;
  background-color: #ffffff;
  padding: 12px 0; /* Vertical padding, no horizontal padding */
  gap: 5px; /* Spacing between images */
  align-items: center; /* Vertically center the images */
  justify-content: center; /* Horizontally center the group of images */
}

.image-container {
  height: 100%;
  background-color: #e0e0e0;
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0; /* Prevent images from shrinking */
}


.image-container img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Set all images to be 50% of the gallery width */
.image-container.left,
.image-container.center,
.image-container.right {
  width: 50%;
}


/* --- Action List (No Change) --- */
.actions-section {
  flex-shrink: 0;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background-color: rgba(242, 242, 247, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.action-group {
  background-color: #ffffff;
  border-radius: 12px;
  overflow: hidden;
}

.action-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px;
  color: #1d1d1f;
  font-size: 1em;
}

.action-item svg {
  color: #007aff;
}

